using System;

namespace SldFile.Binary.FeatureData;

internal sealed class LegacyTutorialFeatureAuthoringTemplate
{
    internal LegacyTutorialFeatureAuthoringTemplate(string sample, string featureName, string className, bool isRevolve, bool isCut, ushort streamVersion, int baseLength, ushort strippedFolderCount, string baseSha256, int markerOffset, uint markerValue, int blockLength, string blockBase64, int endCondition, bool reverseDirection, bool featureScope, bool autoSelect, int scopeBodiesCount, int axisType)
    {
        Sample = sample; FeatureName = featureName; ClassName = className; IsRevolve = isRevolve; IsCut = isCut; StreamVersion = streamVersion;
        BaseLength = baseLength; StrippedFolderCount = strippedFolderCount; BaseSha256 = baseSha256;
        MarkerOffset = markerOffset; MarkerValue = markerValue; BlockLength = blockLength; Block = Convert.FromBase64String(blockBase64);
        EndCondition = endCondition; ReverseDirection = reverseDirection; FeatureScope = featureScope; AutoSelect = autoSelect; ScopeBodiesCount = scopeBodiesCount; AxisType = axisType;
    }
    internal string Sample { get; }
    internal string FeatureName { get; }
    internal string ClassName { get; }
    internal bool IsRevolve { get; }
    internal bool IsCut { get; }
    internal ushort StreamVersion { get; }
    internal int BaseLength { get; }
    internal ushort StrippedFolderCount { get; }
    internal string BaseSha256 { get; }
    internal int MarkerOffset { get; }
    internal uint MarkerValue { get; }
    internal int BlockLength { get; }
    internal byte[] Block { get; }
    internal int EndCondition { get; }
    internal bool ReverseDirection { get; }
    internal bool FeatureScope { get; }
    internal bool AutoSelect { get; }
    internal int ScopeBodiesCount { get; }
    internal int AxisType { get; }
}

internal static class LegacyTutorialFeatureAuthoringTemplates
{
    internal static readonly LegacyTutorialFeatureAuthoringTemplate[] All =
    {
        new LegacyTutorialFeatureAuthoringTemplate("01_pin.sldprt", "Boss-Extrude2", "moExtrusion_c", false, false, 0x6C, 9090, 20, "47a092346bc340689bbd60ab5df8d1c6549c2f50b35ed2bf6f813272e8ac144b", 7062, 10001u, 5713, "", 4, true, true, false, 0, 0),
        new LegacyTutorialFeatureAuthoringTemplate("03_circlip.sldprt", "Base-Extrude", "moExtrusion_c", false, false, 0x67, 12205, 19, "94bfa9533ddc740d3f67b312edc06e840777c8f08cc442d5f3f2fe89f8d90817", -1, 0u, 2764, "", 4, false, false, false, 0, 0),
        new LegacyTutorialFeatureAuthoringTemplate("05_s_632_1.sldprt", "Boss-Revolve1", "moRevolution_c", true, false, 0x78, 26131, 19, "9eb9d6402ac776555e43cb8ee2bd476efe1bc8859da62855343fdb09797ec340", -1, 0u, 8914, "", 0, false, false, false, 0, 10),
        new LegacyTutorialFeatureAuthoringTemplate("09_strain_relief_straight.sldprt", "Cut-Revolve1", "moRevCut_c", true, true, 0x70, 63051, 26, "3c5747ad5a1299a82328404cd3587431d9b2067795952829c0a28ce8d0ed1d53", 47007, 37u, 6642, "", 0, false, true, false, 1, 5)
    };
    internal static LegacyTutorialFeatureAuthoringTemplate? FindByBase(byte[] stream, bool revolve)
    {
        if (stream == null) return null;
        byte[] norm = (byte[])stream.Clone(); if (norm.Length >= 6) { norm[4] = 0; norm[5] = 0; }
        string sha; using (var h = System.Security.Cryptography.SHA256.Create()) sha = BitConverter.ToString(h.ComputeHash(norm)).Replace("-", "").ToLowerInvariant();
        return Array.Find(All, t => t.IsRevolve == revolve && t.BaseLength == stream.Length && t.BaseSha256 == sha);
    }
}
